from pathlib import Path
import json, hashlib, re
ROOT=Path(__file__).resolve().parents[3]
OUT=Path(__file__).parent
VERSION='r6-author-candidate-1'
materials=[];stations=[];writes=[]
def mat(id,title,quest,kind,spot,paragraphs,root=None,access='public'):
 m=dict(id=id,content_version=VERSION,translation_version=VERSION+'-zh1',title_zh=title,quest_ref=quest,kind=kind,location=dict(scene=spot.split('.')[0],spot=spot),source_root=root or id.lower()+'-original',access_class=access,review_status='original_unreviewed',human_review='human_pending',audio_asset='',paragraphs=[dict(id=id+'-p'+str(n+1).zfill(2),en=en,zh=zh) for n,(en,zh) in enumerate(paragraphs)])
 materials.append(m);return m
def brief(id,title,quest,spot,en,zh,access='public'):return mat(id,title,quest,'mission_document',spot,[(en,zh)],access=access)
def act(action,spot,label):stations.append(dict(id='R6-A-'+action.upper(),spot=spot,label_zh=label,action=action))
brief('R6-Q601-R-LANDING','风暴锚地的有限核查入口','Q-601','R6-S01.guide',
 'The present voyage carries the old city’s verified handover into Stormreach. Mara has been rescued and directly identified there; retain the separately established design, policy and execution responsibilities. At this public berth, register the actual Glimmer and current inquiry before seeking the frontier survey. The inquiry covers current network risk and preparation. It does not choose a final policy, deliver six tower packages or make every local office agree.',
 '本次航行把旧都已核验交接带到风暴边境。玛拉已获救且身份经现场确认，设计、政策与执行责任分别保留。在公开泊位登记同一微光号和当前核查委托，再申请前沿测站调查。本次范围是当前网络风险与准备，不替玩家选择终局政策，也不交付六塔工包或代地方同意。')
brief('R6-Q601-R-BRIEFING','芬的前沿工作范围和防护包','Q-601','R6-S02.finn',
 'Finn authorises the present survey from the distribution desk. The declared basic protective kit, guide markers and return-line notes belong to this field commission. Check the kit and obtain the forecast before leaving for the pass. Tess can offer local guidance without joining the party. Her formal invitation follows the completed survey. Nobody needs to endorse a distributed policy to get a safe route or a necessary record.',
 '芬在集散台签发本次调查。基础防护包、向导标记和返程说明属于这项现场委托，出发前核对实物并取得预报。泰丝可以作为当地向导提供帮助，正式同行邀请在测站核查后提出。获得安全路和必要记录不要求赞成分布式政策。')
brief('R6-Q601-R-FORECAST','山口当前预报与三条通道','Q-601','R6-S03.forecast',
 'At the current survey stage, the low cut contains pooled mist and the exposed ridge crosses the marked gust channel. The marked leeward corridor stays inside the guide line and has a sheltered return recess. Use the same current-stage forecast and ground markers together. A clear-looking gap is not a verified alternative. Secure the guide markers and deal with the pass hazard before opening the station connection. The forecast is a working-stage observation, not a real-time reading deadline.',
 '当前调查阶段，低切口积雾，暴露脊线横穿标明的阵风通道。标记背风走廊沿向导线通行，带有受遮蔽返程凹处。把同阶段预报与地标共同使用，眼前清亮的缝隙不是已经核验的替代路。固定标记并处置山口危险后才能打开测站连接。预报按世界工作阶段记录，不设置现实阅读截止。')
brief('R6-Q601-R-INSTRUMENT','测站通道、参考标与现场核验','Q-601','R6-S04.instrument',
 'The survey instrument has a labelled zero channel Z and reference channel R. Check Z at 0 and R at 10 after isolating the local drive; these are instrument marks, not the load units used in other districts. Control the station defence, then verify the readings at the present revision. A reconnection or configuration change expires the check. The report concerns current overload risk and bounded essential supply in this survey window. It does not predict an exact storm hour or prove that all fog was created by the towers.',
 '测站仪表有零点Z通道和参考R通道。隔离本地驱动后，核对Z为0、R为10；这些是仪表标记，不与其他地区负荷单位通兑。处置测站防卫后按当前版本核验读数。连接或配置变动会使旧检查过期。报告说明本窗口的过载风险和受限基本供给，不预测准确风暴钟点，也不证明所有雾来自灯塔。')
brief('R6-Q601-R-RETURN','测站内侧巡检回程线','Q-601','R6-S04.return_check',
 'Inspect the inner patrol latch from the station and check both safe landing stands before registering the return line to the distribution desk. The new connection remains usable after the present hazard is controlled. Opening it does not deliver the later ridge cargo. A safe return anchor is an actual reached place with a current inspection; an icon on the regional map is insufficient.',
 '从测站内侧检查巡检门闩和两端安全落点，再登记通往集散台的返程线。处置当前危险后，新连接继续可用，不会因此交付后面的风脊货载。安全返程锚点必须实际到达并有当前检查，地图图标本身不足。')
brief('R6-Q602-R-WORKLIST','六塔两套清单与有限来源','Q-602','R6-S08.worklist',
 'Each tower needs one base isolator, one local backup, two base provisions and two qualified local watch posts. These come from that district’s inspected facility-conservation contract. Baseline work does not consume the player’s marks, personal parts or the Glimmer’s battery. Enhanced work separately needs one controller, two couplers, three transition crates and a reusable trial fixture per tower. Six public finite contracts supply six controllers, twelve couplers, eighteen crates and six fixtures. Reading this list grants none of them. The six local crews have capacity one each; optional companions and combat auxiliaries are separate people.',
 '每塔需要一隔离套、一当地备用组、两基础保全包及两个合格地方值守岗位，来自对应地区受检设施保全合同。基础工作不消费玩家刻币、个人零件或微光号电池。增强每塔另需一控制器、两联络组件、三过渡箱及一可复用试验夹具。六个公开有限合同供六控制器、十二组件、十八箱、六夹具，阅读清单不入账。六地班组各有同期容量一；可选同伴和战斗援勤另行登记。')
brief('R6-Q602-R-CONTRACTS','地区设施保全：公开登记与实物批次','Q-602','R6-S08.contracts',
 'The local conservation contracts identify BASE-TWR-Rn-base_isolator, BASE-TWR-Rn-local_backup and BASE-TWR-Rn-base_provision for R1 through R6. Inspect the original depot manifest at the actual tower worksite, match its current contract version, serials and qualified watch posts, then inspect and deliver the specified items. The ridge packet is inspected at the frontier transfer shed and delivered only at the tower after its real escort. Signed intentions do not count as stock. The published functional crews and their two separate posts are limited local authoring details, not newly recruited core characters.',
 'R1至R6的地方保全合同分别登记BASE-TWR-Rn-base_isolator、BASE-TWR-Rn-local_backup、BASE-TWR-Rn-base_provision。到该塔实际工程工位核对原仓单，匹配现行合同版本、序号及合格岗位，再检查交付规定实物。风脊工包在中转棚受检，真实护送后到塔站交付。签署意愿不算库存。公开班组和两个不同岗位是有范围的地方候选细节，不是新招募核心人物。')
brief('R6-Q602-R-STEPS','同一工程单的规定步骤','Q-602','R6-S08.dispatch',
 'A confirmed work order reserves every required component and all posts together. The next actions are transport, delivery, installation and verification. Execute each declared step through the communication desk or its physical site; menus, sleep and reloading advance nothing. A component already installed stays installed after cancellation. A completed base order preserves present local service and assigns two actual watches. It does not install the enhanced controller or pass its trial.',
 '确认工程单时，所需材料和全部岗位一起预留。接着实际推进运输、交付、安装、核验，可从通信台或现场执行规定步骤；菜单、睡眠、读档不推进。已经安装的组件在取消后仍保持安装。完成基础单保全现有地方服务并登记两个真实值守，不会顺带安装增强控制器或通过试运行。')
brief('R6-Q602-R-TECHNICAL','技术包的有限适用范围','Q-602','R6-S08.technical',
 'The reusable preparation issue technical-d3-v1 follows the academy’s retained failures, current bounded successful configuration and public handover. Controller C, checked reserve, local isolation and qualified duty supported a limited circuit at the tested load. The issue records how to install and inspect that bounded arrangement; it is not a measurement of all six towers. Each district must still inspect its real installation, receive transition supplies, obtain a local trial permit and run the current configuration. Keep the old failed and successful observations.',
 '可复用准备稿technical-d3-v1继承学城保留反例、当前有限成功配置和公开交接。控制器C、受检备用、当地隔离及合格岗位支持已测试负荷下的有限回路。该稿说明如何安装检查这个受限安排，不是六塔全网测量。各地还须检查实际安装、取得过渡供给和地方试验许可，并按当前配置试运行；保留旧成功和失败观察。')
brief('R6-Q602-R-PROTOCOL','地区操作方与代表方的共同条款','Q-602','R6-S08.protocol',
 'Protocol-d3-v1 preserves essential local protection, bounded contact, mutual aid and independent review. Every region supplies two different current appointment instances: its operator and representative. ROLE-Rn-OP acts within operate:Rn; ROLE-Rn-REP within represent:Rn. Neither appointment signs for another district or decides the player’s final policy. Local trial permission may be issued before final common acceptance, so testing and agreement do not wait for each other in a circle. Changed holders or terms require a current signature.',
 'protocol-d3-v1保留地方基本保护、受限联络、互助及独立复核。每地提供操作方与代表方两个不同的现行任职实例。ROLE-Rn-OP只在operate:Rn范围，ROLE-Rn-REP只在represent:Rn范围任职；不为其他地区签字，也不替玩家选终局政策。地方试验许可可先于最终共同接受，避免试验和协议互等。人员或条款改变须重新取得当前签名。')
brief('R6-Q602-R-OVERVIEW','六地准备概览的读法','Q-602','R6-S08.overview',
 'The preparation view reports each tower’s actual current safety, base conservation, enhanced version, transition supply, watch occupants, local permit and field-trial version. Missing is not failed, and installed is not tested. Compare all six places using the current signed receipts. A draft graph may quote those facts, but cannot change them. Q602 closes after the six base results including the ridge tower; enhanced rows may remain incomplete. Q603 needs only its local cargo and route, not all six base results.',
 '准备视图分别报告每塔当前安全、基础保全、增强版本、过渡供给、岗位人员、地方许可与试运行版本。缺项不等于失败，安装不等于已测试。依当前签收回执比较六地；草稿图可以引用事实，不能修改它们。Q602在包含风脊塔的六份基础结果齐备后关闭，增强仍可缺项。Q603只依赖当地货载和路线，不等待六地全齐。')
brief('R6-Q603-R-MANIFEST','风脊基础护送货单','Q-603','R6-S05.manifest',
 'This protected base packet contains one R6 isolator, one local backup and two base provisions. Finn coordinates its local cart; the two declared escort posts are ROLE-R6-CART-DRIVER and ROLE-R6-CARGO-WATCH. Tess may assist as a guide but recruitment is unnecessary. Confirm the actual packet, destination R6-S07, current segment and fallback previous_safe_segment. Packets from optional two-trip transport and enhanced transition crates remain in separate accounts. The cart does not move while a document is open.',
 '受保护基础工包含R6隔离套一、当地备用组一、基础保全包二。芬协调地方货车，两个护送岗位为ROLE-R6-CART-DRIVER、ROLE-R6-CARGO-WATCH。泰丝可作为向导帮助，招募并非必要。确认实物、R6-S07目的地、本段与previous_safe_segment备用方案。可选两趟货载和增强过渡箱分别记账；打开文献时货车不走。')
brief('R6-Q603-R-SEGMENTS','安全行程段与退回边界','Q-603','R6-S05.segment',
 'First inspect and load the packet at the transfer shed. Control the first-segment escort hazard before explicitly starting the outer line. On the outer line, complete the second escort disposition before continuing to the tower. Withdrawal restores the present segment’s entry cargo and combat resources; earlier source inspection, safe route results and saved prose remain. A cargo group can retreat to its previous safe segment, or be deposited under the local cart keeper, but cannot be folded into world-map travel.',
 '先在中转棚检查装运工包，处置首段护送危险，再明确出发进入外线。在外线完成第二护送处置后才继续到塔。撤回恢复本段入口货载和战斗资源，较早来源检查、通路结果与正文保留。货载可退回上一安全段或交地方车守安全托管，不能折叠进世界地图旅行。')
brief('R6-Q603-R-PLATFORM','封锁平台的保护和隔离顺序','Q-603','R6-S07.platform',
 'The platform consists of a main unit and a field device. From the external stand, disconnect_field_input, fix_external_brake and verify_zero_field_energy in that order. Protect the current cargo segment, then isolate the platform after its main threat is controlled. Pressure may reduce the main unit’s impact; it cannot sign a cargo receipt or perform the isolation action. The protected packet reaches the receiving stand only through the actual paired route. Inspect the local return and present configuration before issuing tower safety.',
 '平台由主体和护场器组成。先在外侧工位依次断输入disconnect_field_input、固定制动fix_external_brake、核零能verify_zero_field_energy；再保护本次货载段，主体威胁控制后再实际隔离平台。压强可以减弱主体冲击，不能代签货物回执或执行隔离。受保护工包沿实际成对通路到接收站，核对地方返程和当前配置后才签塔站安全。')
brief('R6-Q603-R-LOCAL','风脊接收、基本保障与维护安排','Q-603','R6-S07.delivery',
 'The receiving team checks all four base components at R6-S07 and retains their serials. Inspect the isolation position, backup connection, minimum protected supply and return route. The same delivered packet can then be consumed by its registered base conservation order. The local watch must be assigned and the four work stages verified before a sixth base reply is sent. Success against the platform alone establishes neither delivery nor base conservation.',
 'R6-S07接收组逐件核对四份基础组件并保留序号。检查隔离、备用连接、最低保护供给和返程线；这份已交付工包随后供给登记的基础保全单。必须指派当地岗位并完成四工作阶段核验，才发送第六份基础答复。击退平台本身不成立交付或基础保全。')
brief('R6-Q603-R-LOAD','两趟补充运输的五箱与容量','Q-603','R6-S05.supplement',
 'Optional supplement PZ-Q603-LOAD has two trips of six spaces each. The whole boxes are tools3, fittings1, lighting4, wind_panels2 and archives2. Tools and fittings must arrive in a trip earlier than lighting; the panels and archives have no fixed order. Both qualified arrangements are accepted. This independent supplement is optional, earns no second parent reward and supplies neither protected base components nor enhanced transition crates. Declining it preserves the base route.',
 '可选PZ-Q603-LOAD共有两趟，每趟六格。整箱体积为tools三、fittings一、lighting四、wind_panels二、archives二。工具和安装件须在早于照明的一趟到达；面板与档案顺序不限。两种合格安排均接受。补充运输独立且可选，不重复发父任务奖励，不供基础组件或增强过渡箱，拒绝后基础路径仍完整。')
brief('R6-Q604-R-QUALIFICATION','起航前公开方案资格与缺项','Q-604','R6-S08.qualification',
 'Six actual base conservations preserve two eventual directions: restricted central operation and orderly disconnection. The central dangerous program must still be made safe in the seventh tower. A distributed direction additionally needs a verified technical package, six enhanced installations, transition supply, six current operator-and-representative agreements and six current field trials. Read each missing item now. Continue actual preparation, use established commissioned crews, or explicitly accept the two base directions. A private arc or language score is not a departure condition.',
 '六塔真实基础保全保留受限中央与有序断联两个后续方向；中央危险程序仍须在第七塔稳定。分布式另需技术包验证、六增强安装、过渡供给、六地区当前操作方与代表方协议、六当前现场试运行。现在逐项看缺失，可以继续准备、使用已建立委托班组或明确接受两个基础方向。个人线和语言分数不构成起航条件。')
brief('R6-Q604-R-COMMITMENTS','高风险承诺登记与交接','Q-604','R6-S08.commitments',
 'The current register includes every accepted on-site commitment and every transport segment in this world branch. A segment with cargo still moving must be actually delivered or deposited safely; a required on-site promise needs safe handover or explicit suspension. Ordinary unaccepted optional work does not block departure. Review the register after any new commitment. An old empty list cannot prove that the present branch has none.',
 '当前登记包含本世界分支全部已承接现场承诺和运输段。正在运输的货物须真实交付或安全托管；必须到场的承诺须安全交接或明确暂缓。普通未接受可选工作不阻止起航。新增承诺后重新核对登记，旧空清单不能证明当前分支无事。')
brief('R6-Q604-R-DEPARTURE','微光号最终起航交接','Q-604','R6-S01.departure',
 'At the frontier communication desk, save the proposed handover, review missing preparations and preserve a named protected pre-final checkpoint. Seal the actual preparation receipts and installed supplies. Then walk aboard the same Glimmer and confirm the current chart station, frontier berth and destination landing. The final launch closes Q604, moves that one vessel and the actor to the seventh-tower sea-cliff entry, and records one actual departure. Outside travel pauses after this confirmation. The central program and final policy remain unfinished.',
 '在边境通信台保存交接提议，核对缺项并保留明确命名的终章前保护存档，封存实际准备回执与已安装供给。然后走上同一微光号，在当前航图站核对边境泊位和目的落点。最终起航一次关闭Q604，并将同一船和玩家实际移到第七塔海崖入口，留下唯一实际出发。确认后暂停外区旅行；中央程序和最终政策尚未完成。')
brief('R6-CQTESS01-R-CONTACTS','两个接收点的地方联系人','CQ-TESS-01','R6-S05.contacts',
 'For this private local coordination task, the existing transfer-shed receiver ROLE-R6-SHED-RECEIVER accepts complete labelled boxes against the present manifest; the ridge receiver ROLE-R6-RIDGE-RECEIVER accepts them after a safe segment arrival and checks the same version. Confirm both contacts and those receiving conditions with Tess’s current invitation. These are two existing main-route receiving functions, not hidden settlements needed for an ending. The task can be deferred without taking their protected basic supplies away.',
 '本人邀请下的地方协调涉及既有中转棚接收岗ROLE-R6-SHED-RECEIVER和风脊接收岗ROLE-R6-RIDGE-RECEIVER。前者依现行货单接受整箱标记货物，后者在安全段抵达后核同一版本。明确两名联系人及收货条件；它们是两处已有主线路径岗位，不是结局必须隐藏聚落。暂缓此项不撤走基础供给。',access='individual_permission')
brief('R6-CQTESS02-R-TRIPS','两趟取舍的原回执','CQ-TESS-02','R6-S05.supplement',
 'Refer to the original supplement receipts if the two trips were accepted and actually delivered. Record which complete boxes arrived first and why that choice suited the local plan. If no supplement was promised, record not_committed rather than inventing arrival. This node cites existing work; it does not reserve a second batch, repeat the journey or grant experience, marks or parts.',
 '承接且实际送达两趟补充货载后，引用原回执说明哪些整箱先到及其理由。未承诺运输时写not_committed，不虚构抵达。本节点只引用既有工作，不另留一批、不重复旅程、不发经验刻币零件。',access='individual_permission')
brief('R6-CQTESS03-R-NOTICE','下一班的通知链和同版记录','CQ-TESS-03','R6-S08.local_notice',
 'Finn keeps the current delivery sheet with ROLE-R6-NEXT-WATCH. Tess asks the sender to preserve the original contact and add ROLE-R6-NOTICE-BACKUP, both able to see the same current record. Send the bounded local notice, obtain the receiving team’s actual confirmation and keep any remaining check visible. This is a local watch handover, not a signature for the six-region operating protocol. Tess’s policy disagreement does not erase completed work.',
 '芬与ROLE-R6-NEXT-WATCH保存当前交付表。泰丝要求保留原联系人，再加ROLE-R6-NOTICE-BACKUP，二者都能看同一当前版本。发有限地方通知，取得接收班实际确认并列余下检查。这是地方值守交接，不是六地区运行协议签字；泰丝的政策分歧不抹去已做工作。',access='individual_permission')
brief('R6-O01-R-NEEDS','外缘聚落甲的可选增补需求','O-R6-01','R6-O01.notice','The settlement asks for an optional comparison of its forecast and additional needs. Its protected minimum is already included in the main provision plan. A proposed extra delivery remains unaccepted until its own route and stock are confirmed; it cannot be used as a hidden ending key.','聚落请求可选预报与额外需求比较。受保护最低保障已含主线供给，增补尚须独立确认路线库存，不能用作隐藏结局钥匙。')
brief('R6-O02-R-MAINTENANCE','外缘聚落乙的共享设备登记','O-R6-02','R6-O02.notice','The settlement records a shared maintenance question without claiming that its tools have been delivered. Visit or defer the optional contact freely. No required baseline component, final protocol signature or trial receipt is concealed here.','聚落记录共享维护问题，尚未宣称设备送到。可自由到访或暂缓，不在此隐藏必需基础组件、协议签字或试验回执。')
# Long reads and listening scripts are completed below; scripts have no recording claim.
mat('R6-Q603-L-ESCORT','关键听力脚本：两段货载交接','Q-603','listening_script','R6-S05.segment',[
 ('Finn: Match the four protected serials against the manifest. The cart driver and cargo watch travel under this local commission. A recruited guide may help, but does not create another component.','芬：对四件保护序号。车司机与货守依本次地方委托执行。同伴向导可以帮助，却不创造另一件组件。'),
 ('Cargo watch: After the first hazard is controlled, confirm departure into the outer segment. We will not skip that confirmation while the notice is open. On withdrawal, preserve the earlier source inspection and restore this attempt to its recorded entry.','货守：首段危险控制后明确外线出发，打开通知时不跳过确认。撤回保留较早来源检查，并把本次尝试恢复入口。'),
 ('Tess: The outer segment needs its own actual result before the paired tower entrance opens. If we cannot continue, use the present safe return or deposit the packet with its named cart keeper. Do not take a moving cargo group into ordinary sea travel.','泰丝：外线要自己的结果才开配对塔口。不能继续时走安全返程或交指定车守托管，不能把移动货组带入普通航海。')])
mat('R6-Q603-L-RECEIPT','关键听力脚本：风脊逐件接收','Q-603','listening_script','R6-S07.delivery',[
 ('Receiver: I need the same four serials that left the shed, the two safe escort results and the actual present receiving stand. The platform battle is one of the safety results, not my signature.','接收岗：要棚出发的同四序号、两安全护送结果和当前真实接收站。平台战是一个安全结果，不是我的签字。'),
 ('Finn: Control the field device, protect this packet and stop the platform. Then isolate it and inspect the return. Only the current configuration can support the tower safety record. The baseline order consumes the received components later; an enhanced controller is a separate item.','芬：制护场器、护本批、停平台，再隔离核返程。只有当前配置支持安全记录。基础单之后才消耗已接组件，增强控制器另算。')])
mat('R6-Q604-L-HANDOVER','关键听力脚本：封存前的公开核对','Q-604','listening_script','R6-S08.qualification',[
 ('Finn: Six actual baselines preserve the two base directions. The distributed list has additional current work. Look at every missing item and choose whether to continue preparing or proceed with the established base directions. A private invitation is not a hidden condition.','芬：六真实基础保留两个方向，分布式另有当前工作。逐项看缺失，选继续或按基础方向出发，个人邀请不是隐藏条件。'),
 ('Tess: Current moving cargo must arrive or be safely deposited. Accepted attendance promises need a real handover or explicit suspension. Preserve the protected checkpoint, seal the actual supplies and walk to the same Glimmer chart. Our final policy remains unselected, and the seventh tower still has dangerous work ahead.','泰丝：现移动货须到或安全托管，到场承诺要交接或暂缓。留保护档、封实供、走同一微光海图。最终政策未选，第七塔危险工作仍在前方。')])
